package ug.audiocity.studio;
import java.io.*;import java.nio.file.*;import java.util.*;
public final class PatternRepeatSpacingTests {
 static int n;static void ok(boolean b,String why){n++;if(!b)throw new AssertionError(why);}static void clean(File f){if(f.isDirectory())for(File c:f.listFiles())clean(c);f.delete();}
 static float[][] kit(){float[][] wave=new float[8][];for(int i=0;i<8;i++){wave[i]=new float[100];Arrays.fill(wave[i],.1f);}return wave;}
 public static void main(String[] args)throws Exception{File dir=Files.createTempDirectory("acs-repeat-spacing-").toFile();try{
  Core.Session s=new Core.Session();s.directory=dir.getAbsolutePath();s.bpm=240;long bar=Core.beat(240)*4;float[][] kit=kit();BeatPilotDrumPattern one=new BeatPilotDrumPattern(240,1);one.set(0,0,0,112);one.set(0,1,4,98);PatternLibrary.Entry entry=PatternLibrary.add(s,"Pattern 1",one);PatternArrangement.place(s,entry.id,kit,0,8);
  BeatPilotDrumPattern eight=one.resizedEmpty(8);eight.set(7,2,15,96);PatternArrangement.save(s,entry.id,"Pattern 1",eight,kit);
  for(Core.Track track:s.tracks)for(int i=0;i<8;i++){Core.Clip clip=track.clips.get(i);ok(clip.start==i*8*bar,"growing a placed one-bar pattern to eight bars re-spaces every channel repeat");ok(clip.length==8*bar,"each repeat keeps the full eight-bar performance");}
  PatternArrangement.save(s,entry.id,"Pattern 1",one,kit);for(Core.Track track:s.tracks)for(int i=0;i<8;i++)ok(track.clips.get(i).start==i*bar,"shrinking restores consecutive repeat spacing");
  // Recreate the screenshot: eight-bar copies whose starts are still one bar apart.
  PatternArrangement.save(s,entry.id,"Pattern 1",eight,kit);Core.Clip first=s.tracks.get(0).clips.get(0);first.gain=.42;s.tracks.get(0).pan=-.3;String file=first.file;Core.Source original=first.source;for(Core.Track track:s.tracks)for(int i=0;i<8;i++)track.clips.get(i).start=i*bar;Core.Session undo=s.copy();
  ok(s.tracks.size()==3,"only the kick, snare and clap lanes the pattern uses have tracks");ok(PatternArrangement.repairOverlaps(s)==21,"repair moves seven overlapping copies on each used channel");for(Core.Track track:s.tracks)for(int i=0;i<8;i++)ok(track.clips.get(i).start==i*8*bar,"already-saved overlapping copies are re-spaced consecutively");ok(first==s.tracks.get(0).clips.get(0)&&first.file.equals(file)&&first.source==original&&first.gain==.42&&s.tracks.get(0).pan==-.3,"repair preserves selected clip identity, original audio and independent mixer edits");ok(undo.tracks.get(0).clips.get(1).start==bar,"Undo snapshot retains pre-repair positions");ok(PatternArrangement.repairOverlaps(s)==0,"repair is idempotent");
  ProjectIO.save(s);Core.Session opened=AudioIO.load(dir);ok(opened.tracks.get(2).clips.get(7).start==56*bar,"fixed spacing survives reopening the project");
  int count=s.tracks.get(0).clips.size(),files=dir.list().length;try{PatternArrangement.place(s,entry.id,kit,bar,1);throw new AssertionError("partial overlap allowed");}catch(IllegalArgumentException expected){n++;}ok(s.tracks.get(0).clips.size()==count&&dir.list().length==files,"placing inside an eight-bar instance cannot create another layer or partial files");
  Core.Session limit=new Core.Session();limit.bpm=240;limit.directory=dir.getAbsolutePath();PatternLibrary.Entry near=PatternLibrary.add(limit,"Near end",one);long at=Core.MAX_FRAMES-8*bar;PatternArrangement.place(limit,near.id,kit,at,8);Core.Clip before=limit.tracks.get(0).clips.get(1);String oldData=PatternLibrary.find(limit,near.id).data;files=dir.list().length;try{PatternArrangement.save(limit,near.id,"Too long",eight,kit);throw new AssertionError("repeat extension beyond project accepted");}catch(IllegalArgumentException expected){n++;}ok(before==limit.tracks.get(0).clips.get(1)&&before.start==at+bar&&oldData.equals(PatternLibrary.find(limit,near.id).data)&&dir.list().length==files,"invalid growth fails before changing any copies, pattern metadata or source files");
  // An unrelated later section is not silently moved to make room.
  Core.Session collision=new Core.Session();collision.bpm=240;collision.directory=dir.getAbsolutePath();PatternLibrary.Entry a=PatternLibrary.add(collision,"Verse",one),b=PatternLibrary.add(collision,"Chorus",one);PatternArrangement.place(collision,a.id,kit,0,2);PatternArrangement.place(collision,b.id,kit,2*bar,1);try{PatternArrangement.save(collision,a.id,"Verse",one.resizedEmpty(2),kit);throw new AssertionError("growth into unrelated section accepted");}catch(IllegalArgumentException expected){n++;}ok(collision.tracks.get(0).clips.get(1).start==bar&&collision.tracks.get(0).clips.get(2).start==2*bar,"unrelated section and repeat starts remain untouched after conflict");
  System.out.println("PatternRepeatSpacingTests passed "+n+" checks");
 }finally{clean(dir);}}
}
